```js
// Stateless /mcp handler — ONE McpServer + ONE transport PER POST. Not a singleton.
import http from 'node:http';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';

http.createServer(async (req, res) => {
  if (req.method !== 'POST') {                       // GET + DELETE
    res.writeHead(405, { Allow: 'POST', 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ jsonrpc: '2.0', error: { code: -32000, message: 'Method not allowed.' }, id: null }));
    return;                                          // client swallows this silently
  }
  const mcp = new McpServer({ name: 'gateway', version: '0.0.1' });
  // ...registerTool(...) per request
  const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined });
  res.on('close', () => { transport.close(); mcp.close(); });   // required, else handles leak
  await mcp.connect(transport);
  await transport.handleRequest(req, res);           // do NOT reuse `transport` for the next request
}).listen(8787, '127.0.0.1');
```
Client side needs nothing special — plain `new Client(...)` + `new StreamableHTTPClientTransport(new URL(url))` works against the above unchanged.
